args.Content:
$ErrorActionPreference = 'Stop'
$art = 'C:\Users\Admin\.gemini\antigravity\brain\de950b82-917a-4475-8f4e-96dbc80978aa'
$htmlPath = "$art\scratch\korean_render_test.html"

Add-Type -AssemblyName PresentationCore
$cps = @(0xC0AC, 0xB791, 0xD574, 0xAE30, 0xC5B5, 0xC544, 0xC774, 0xC624, 0xC5F0, 0xC560, 0xC758, 0xC870, 0xAC74)
foreach ($fn in @('NotoSansKR-Regular.otf', 'NotoSansKR-Medium.otf', 'NotoSansKR-Bold.otf')) {
    $fp = "$env:windir\Fonts\$fn"
    if (-not (Test-Path $fp)) { throw "Missing $fp" }
    $gt = New-Object System.Windows.Media.GlyphTypeface (New-Object System.Uri($fp))
    $missing = @()
    foreach ($cp in $cps) {
        [uint16]$gid = 0
        if (-not $gt.CharacterToGlyphMap.TryGetValue($cp, [ref]$gid) -or $gid -eq 0) {
            $missing += ('U+{0:X4}' -f $cp)
        }
    }
    Write-Output ("GLYPH_CHECK {0} Family='{1}' Missing=[{2}]" -f $fn, $gt.FamilyNames['en-us'], ($missing -join ','))
    if ($missing.Count -gt 0) { throw "Missing glyphs in $fn" }
}
& icacls.exe "$env:windir\Fonts\NotoSansKR-Regular.otf" | Select-String 'ALL APPLICATION PACKAGES|Users' | ForEach-Object { "ACL: $($_.Line.Trim())" }

$src = "$env:APPDATA\Mozilla\Firefox\Profiles\s22bx8y4.default-release"
$dst = "$env:TEMP\ff_font_verify"
if (Test-Path $dst) { Remove-Item $dst -Recurse -Force }
New-Item -ItemType Directory -Force -Path $dst | Out-Null
Copy-Item "$src\chrome" "$dst\chrome" -Recurse -Force
foreach ($f in @('user.js', 'prefs.js', 'compatibility.ini', 'times.json', 'xulstore.json', 'extensions.json', 'addonStartup.json.lz4', 'containers.json')) {
    if (Test-Path "$src\$f") { Copy-Item "$src\$f" "$dst\$f" -Force }
}
if (Test-Path "$src\extensions") { Copy-Item "$src\extensions" "$dst\extensions" -Recurse -Force }
$prefsLines = Get-Content "$dst\prefs.js" | Where-Object { $_ -notmatch 'toolkit\.startup\.recent_crashes|browser\.sessionstore\.crashed|browser\.startup\.homepage|didSeeAboutWelcome|aboutwelcome\.enabled' }
$prefsLines | Set-Content "$dst\prefs.js" -Encoding UTF8
$testUri = ([System.Uri]$htmlPath).AbsoluteUri
Add-Content "$dst\user.js" "`nuser_pref(""browser.aboutwelcome.enabled"", false);`nuser_pref(""browser.startup.homepage_override.mstone"", ""ignore"");`nuser_pref(""trailhead.firstrun.didSeeAboutWelcome"", true);`nuser_pref(""browser.startup.page"", 1);`nuser_pref(""browser.startup.homepage"", ""$testUri"");"

Add-Type -AssemblyName System.Drawing
$cs = @"
using System;
using System.Text;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
public class FfFontVerify {
    public delegate bool EnumProc(IntPtr h, IntPtr l);
    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc p, IntPtr l);
    [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
    [DllImport("user32.dll")] public static extern int GetClassName(IntPtr h, StringBuilder sb, int max);
    [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
    [DllImport("user32.dll")] static extern bool PrintWindow(IntPtr hWnd, IntPtr hdcBlt, uint nFlags);
    [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
    public static void Snap(IntPtr hwnd, string outPng) {
        RECT rc; GetWindowRect(hwnd, out rc);
        int w = Math.Max(50, rc.Right - rc.Left);
        int h = Math.Max(50, rc.Bottom - rc.Top);
        using (Bitmap bmp = new Bitmap(w, h)) {
            using (Graphics g = Graphics.FromImage(bmp)) {
                IntPtr hdc = g.GetHdc();
                PrintWindow(hwnd, hdc, 2);
                g.ReleaseHdc(hdc);
            }
            bmp.Save(outPng, ImageFormat.Png);
        }
    }
    public static IntPtr[] FindPidWindows(int targetPid, string clsFilter) {
        List<IntPtr> res = new List<IntPtr>();
        EnumWindows((h, l) => {
            uint pid = 0; GetWindowThreadProcessId(h, out pid);
            if ((int)pid == targetPid && IsWindowVisible(h)) {
                StringBuilder sb = new StringBuilder(256);
                GetClassName(h, sb, 256);
                if (string.IsNullOrEmpty(clsFilter) || sb.ToString() == clsFilter) res.Add(h);
            }
            return true;
        }, IntPtr.Zero);
        return res.ToArray();
    }
}
"@
Add-Type -TypeDefinition $cs -ReferencedAssemblies System.Drawing

$testPid = 0
try {
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = 'C:\Program Files\Mozilla Firefox\firefox.exe'
    $psi.Arguments = "-no-remote -no-launcher -profile `"$dst`""
    $psi.UseShellExecute = $false
    $proc = [System.Diagnostics.Process]::Start($psi)

    $hwnd = [IntPtr]::Zero
    for ($i = 1; $i -le 18; $i++) {
        Start-Sleep -Seconds 1
        $cands = Get-CimInstance Win32_Process -Filter "Name='firefox.exe'" | Where-Object { $_.CommandLine -like "*ff_font_verify*" -and $_.CommandLine -notlike "*-contentproc*" }
        foreach ($c in $cands) {
            $wins = [FfFontVerify]::FindPidWindows([int]$c.ProcessId, 'MozillaWindowClass')
            if ($wins.Length -gt 0) {
                $testPid = [int]$c.ProcessId
                $hwnd = $wins[0]
                break
            }
        }
        if ($hwnd -ne [IntPtr]::Zero) { break }
    }
    if ($hwnd -eq [IntPtr]::Zero) { throw 'Test Firefox window did not open' }
    Start-Sleep -Seconds 4
    $wTitle = (Get-Process -Id $testPid -ErrorAction SilentlyContinue).MainWindowTitle
    Write-Output ("WINDOW_TITLE_LEN=" + $wTitle.Length)
    [FfFontVerify]::Snap($hwnd, "$art\verify_korean_fonts_live.png")
} finally {
    if ($testPid -gt 0) {
        $pTest = Get-Process -Id $testPid -ErrorAction SilentlyContinue
        if ($pTest) {
            $null = $pTest.CloseMainWindow()
            for ($i = 0; $i -lt 10; $i++) {
                Start-Sleep -Milliseconds 500
                if ($pTest.HasExited) { break }
            }
        }
    }
    Get-CimInstance Win32_Process -Filter "Name='firefox.exe'" | Where-Object { $_.CommandLine -like "*ff_font_verify*" } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
    Start-Sleep -Milliseconds 500
    Remove-Item $dst -Recurse -Force -ErrorAction SilentlyContinue
}
